// Temporary measurement script: bundles the HEAD version of src/ with the same esbuild options as
// test/bench/bundle.test.ts, then removes its own scratch folder.
import { execSync } from "node:child_process";
import { mkdirSync, writeFileSync, rmSync } from "node:fs";
import path from "node:path";
import zlib from "node:zlib";
import { build } from "esbuild";

const root = ".baseline-check";
const files = execSync("git ls-tree -r --name-only HEAD src", { encoding: "utf8" })
  .trim()
  .split("\n");

rmSync(root, { recursive: true, force: true });
for (const file of files) {
  const dest = path.join(root, file);
  mkdirSync(path.dirname(dest), { recursive: true });
  writeFileSync(dest, execSync(`git show HEAD:${file}`, { maxBuffer: 1 << 26 }));
}

const cases = {
  H3: `import { H3 } from "./${root}/src/index.ts"; const app = new H3();`,
  H3Core: `import { H3Core } from "./${root}/src/index.ts"; const app = new H3Core();`,
  defineHandler: `import { defineHandler } from "./${root}/src/index.ts"; const handler = defineHandler({});`,
};

for (const [name, code] of Object.entries(cases)) {
  const res = await build({
    bundle: true,
    metafile: true,
    write: false,
    minify: true,
    format: "esm",
    platform: "node",
    outfile: "index.mjs",
    treeShaking: true,
    conditions: ["browser"],
    logOverride: { "ignored-bare-import": "silent" },
    stdin: { contents: code, resolveDir: process.cwd(), sourcefile: "index.mjs", loader: "js" },
  });
  const { bytes } = res.metafile.outputs["index.mjs"];
  const gzip = zlib.gzipSync(res.outputFiles[0].text).byteLength;
  console.log(`BASELINE ${name}: bytes=${bytes} gzip=${gzip}`);
}

rmSync(root, { recursive: true, force: true });
console.log("scratch folder removed");

